$rosters=[];$classes=[];
foreach(csdl_classes_all() as $c)if(is_array($c)&&(!array_key_exists('active',$c)||$c['active'])){$name=trim((string)($c['name']??''));if($name!==''){$classes[(string)($c['id']??'')]=$name;$rosters[$name]=[];}}
foreach(csdl_students_all() as $s)if(is_array($s)&&(!array_key_exists('active',$s)||$s['active'])){$name=trim((string)($s['name']??$s['ho_ten']??''));$class=trim((string)($s['class_name']??$s['class']??$s['lop']??''));if($class===''&&!empty($s['class_id']))$class=$classes[(string)$s['class_id']]??'';if($class!==''&&$name!=='')$rosters[$class][]=$name;}
uksort($rosters,'csdl_compare_class_names');$base=defined('BASE_URL')?BASE_URL:'/';$school=defined('SCHOOL_NAME')?SCHOOL_NAME:'CDS';
